        //   postEffects:  array of post-impact step names from:
        //                 'chargeToTarget', 'selfStun', 'chain', 'drainHop',
        //                 'swap', 'pull', 'push', 'displacement', 'aoeOnArrival',
        //                 'leaveTerrain', 'terrainDeform', 'spawnDecoy'
