            unitAt3D, unitsAtColumn, getTerrainAt3D, dist3D, distXY, combatDist, combatReach,
            buildColumnsFromLegacy, buildColumnsFromVoxels, ensureUnitZCoords,

            aliveUnitsFor, aliveUnitsOnFloor, enemyOf, unitDisplayName,
            getHostileUnits, isBossUnit, getBossOccupiedTiles,
            isAllyUnit, isEnemyUnit, _isFFA,
            unitAt, canFly, isUnitAirborne, airborneUnitAt, getMinFlyingZ, getMaxFlyingZ,
            isFlightCrippled, forceGroundUnit,
            canFlyToSky, canDescendUnderground, canReturnToGround,
            unitHasJetpack, unitHasSpelunkingGear,
            SKY_RACES, UNDERGROUND_RACES, unitFinished,
            getEffectiveRange, getEffectiveSpellRange, getEffectiveMove, getEffectiveAwr,
            getRangeDamageMult, computeSpellBase,
            /* Seeded engine RNG (state.js) — ai.js and console tooling reach
               it through GAME; engine code calls the globals directly. */
            engineRng, engineRandInt, seedEngineRng,
            getEffectiveAttackBonus, getHourglassPower, getSpellStatBonus,
            getStatusArmorDelta, getStatusMdefDelta, getStatusAtkDelta, getStatusIntDelta,
            getStatStageCount, applyStatStageBoost,
            getUnitLevel, getXPProgressPct, xpProgressionActive,

            canUnitAct, canUnitMove,
            // The ONE validity/targeting oracle (pure, read-only — safe on
            // host AND guest). All consumers converge on this; the legacy
            // validity globals below are delegates into it.
            TargetQuery,
            canAffordSpell, getSpellApCost, getSpellCooldownRemaining,
            getCritChance, getEvasionChance,
            getMoveTiles, getAttackTiles, getInspectTiles, getSpellRangeTiles,
            getJumpTiles, canJump, getUnitJumpStat, getUnitJumpClimb, getUnitJumpReach,
            getJumpBlockedTiles, findRouteTo,
            isRangeBlockedByTerrain, getLinePoints,
            unitHasStatus, unitHasFlair, unitHasWard,
            isUnitConcealedFrom, isUnitSeenByAnyEnemy, isUnitSeenByTeam, checkStealthReveals,
            unitHasTelescope, getTelescopeSkyTargets,

            getTerrainAt, getTerrainRule, getEntranceAt, getHeightAt, getBaseHeightAt, getUnitStandingHeight,
