            get CLASS_SPELL_LEARN_ORDER() { return typeof CLASS_SPELL_LEARN_ORDER !== 'undefined' ? CLASS_SPELL_LEARN_ORDER : {}; },
            get SPELL_SHOP_PRICES() { return typeof SPELL_SHOP_PRICES !== 'undefined' ? SPELL_SHOP_PRICES : {}; },
            learnSpellForUnit,
            applySecondaryJob,
            aiPickSecondaryJob,
