                        // (1 AP beats 2) — takeoff tiles only where walking can't go.
                        const _walkCols = new Set(tiles.map(t => posKey(t.x, t.y)));
                        const savedZ = unit.z;
                        unit.z = _toZ;   // simulate the post-takeoff unit (isUnitAirborne → true)
